"""Manual GitHub Releases checks and verified staging; no startup networking."""
import ctypes
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import subprocess
import tempfile
from urllib.parse import quote, urlsplit
from urllib.request import Request, urlopen
import uuid
import zipfile

from .portable_tray_actions import launcher_path

MAX_PACKAGE = 8 * 1024**3
MAX_EXPANDED = 16 * 1024**3


def root_path():
    return launcher_path().parent


def release_config(root=None):
    return json.loads(((root or root_path()) / "WhisperKey/config/release.json").read_text(encoding="utf-8"))


def version(value):
    # Stable releases only; prereleases are rejected, not ordered ambiguously.
    match = re.fullmatch(r"v?(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:\+[0-9A-Za-z.-]+)?", value)
    if not match:
        raise ValueError("Expected a stable semantic version")
    return tuple(int(part) for part in match.groups())


def fetch_metadata(url):
    request = Request(url, headers={"Accept": "application/vnd.github+json", "User-Agent": "EXPC-WLK-updater"})
    with urlopen(request, timeout=10) as response:
        data = response.read(2 * 1024**2 + 1)
    if len(data) > 2 * 1024**2:
        raise ValueError("Release metadata too large")
    return json.loads(data)


def check_latest(config=None, fetch=fetch_metadata):
    config = config or release_config()
    repo = config.get("repository", "")
    if not repo:
        return {"status": "not_configured"}
    if not re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", repo):
        raise ValueError("Invalid official repository")
    data = fetch(f"https://api.github.com/repos/{repo}/releases/latest")
    if data.get("draft") or data.get("prerelease"):
        raise ValueError("Only published stable releases are supported")
    current, latest = version(config["version"]), version(data["tag_name"])
    if latest <= current:
        return {"status": "up_to_date" if latest == current else "older"}
    assets = [a for a in data.get("assets", []) if a.get("name") == config["asset_name"]]
    if len(assets) != 1:
        raise ValueError("Official portable asset missing or ambiguous")
    asset = assets[0]
    url = asset["browser_download_url"]
    expected = f"https://github.com/{repo}/releases/download/{quote(data['tag_name'], safe='')}/{quote(config['asset_name'], safe='')}"
    if url != expected or not re.fullmatch(r"sha256:[a-fA-F0-9]{64}", asset.get("digest", "")):
        raise ValueError("Official asset URL or SHA-256 digest invalid")
    if not 0 < asset.get("size", 0) <= MAX_PACKAGE:
        raise ValueError("Invalid asset size")
    return {"status": "available", "version": data["tag_name"], "url": url,
            "sha256": asset["digest"][7:].lower(), "size": asset["size"], "repository": repo}


def download(result, destination):
    request = Request(result["url"], headers={"User-Agent": "EXPC-WLK-updater"})
    total = 0
    digest = hashlib.sha256()
    with urlopen(request, timeout=20) as response, Path(destination).open("xb") as output:
        final = urlsplit(response.url)
        if final.scheme != "https" or final.hostname not in ("github.com", "release-assets.githubusercontent.com", "objects.githubusercontent.com"):
            raise ValueError("Unexpected asset redirect")
        while chunk := response.read(1024**2):
            total += len(chunk)
            if total > result["size"] or total > MAX_PACKAGE:
                raise ValueError("Download exceeds published size")
            digest.update(chunk)
            output.write(chunk)
    if total != result["size"] or digest.hexdigest() != result["sha256"]:
        raise ValueError("Download integrity verification failed")


def safe_member(name):
    if "\\" in name or ":" in name or name.startswith("/"):
        raise ValueError("Unsafe archive path")
    parts = PurePosixPath(name).parts
    if not parts or any(p in (".", "..") or p.endswith((".", " ")) for p in parts):
        raise ValueError("Unsafe archive path")
    for part in parts:
        if part.split(".")[0].upper() in {"CON", "PRN", "AUX", "NUL", *(f"COM{i}" for i in range(10)), *(f"LPT{i}" for i in range(10))}:
            raise ValueError("Reserved Windows name")
    lower = name.lower()
    if any(p.lower() in ("user_settings.yaml", "vocabulary.db", "commands.yaml") or p.lower().endswith((".db", ".db-wal", ".db-shm")) for p in parts):
        raise ValueError("User data cannot be shipped in updates")
    allowed = lower in ("expc-wlk.exe", "readme.md") or lower.startswith(("whisperkey/app/", "whisperkey/runtime/", "whisperkey/config/"))
    if not allowed:
        raise ValueError("Package contains non-application data")
    return parts


def stage_archive(archive, expected_hash, expected_version, destination):
    archive, destination = Path(archive), Path(destination)
    with archive.open("rb") as stream:
        if hashlib.file_digest(stream, "sha256").hexdigest() != expected_hash:
            raise ValueError("SHA-256 mismatch")
    if destination.exists():
        raise ValueError("Stage must be new")
    with zipfile.ZipFile(archive) as package:
        files = [entry for entry in package.infolist() if not entry.is_dir()]
        names = set()
        total = 0
        for entry in files:
            safe_member(entry.filename)
            key = entry.filename.lower()
            if key in names or (entry.external_attr >> 16) & 0o170000 == 0o120000:
                raise ValueError("Duplicate path or symbolic link")
            names.add(key)
            total += entry.file_size
        if total > MAX_EXPANDED or len(files) > 100000:
            raise ValueError("Expanded package too large")
        required = {"expc-wlk.exe", "whisperkey/runtime/pythonw.exe", "whisperkey/runtime/python312.dll",
                    "whisperkey/app/portable_boot.py", "whisperkey/config/release.json", "whisperkey/config/portableupdater.exe"}
        if not required <= names:
            raise ValueError("Incomplete portable application package")
        metadata = json.loads(package.read(next(e for e in files if e.filename.lower() == "whisperkey/config/release.json")))
        if version(metadata["version"]) != version(expected_version):
            raise ValueError("Package/release version mismatch")
        destination.mkdir()
        try:
            for entry in files:
                target = destination.joinpath(*safe_member(entry.filename))
                target.parent.mkdir(parents=True, exist_ok=True)
                with package.open(entry) as source, target.open("xb") as output:
                    shutil.copyfileobj(source, output)
        except Exception:
            shutil.rmtree(destination)
            raise
    return destination


def prepare_update(result):
    root = root_path()
    work = Path(tempfile.mkdtemp(prefix=".EXPC-WLK-update-", dir=root.parent))
    try:
        archive = work / "release.zip"
        download(result, archive)
        stage = stage_archive(archive, result["sha256"], result["version"], work / "stage")
        # Repository trust remains pinned across releases.
        config = release_config(stage)
        config["repository"] = result["repository"]
        (stage / "WhisperKey/config/release.json").write_text(json.dumps(config, indent=2), encoding="utf-8")
        helper = work / "PortableUpdater.exe"
        shutil.copyfile(root / "WhisperKey/config/PortableUpdater.exe", helper)
        archive.unlink()
        return work, stage, helper
    except Exception:
        shutil.rmtree(work)
        raise


def offer_update(result, language, quit_app):
    ru = language == "ru"
    prompt = ("Скачать и установить обновление {version}? Приложение будет перезапущено." if ru else
              "Download and install {version}? The application will restart.").format(**result)
    if ctypes.windll.user32.MessageBoxW(None, prompt, "EXPC-WLK", 0x24) != 6:
        return
    work, stage, helper = prepare_update(result)
    prompt = "Обновление проверено. Завершить диктовку и перезапустить сейчас?" if ru else "Update verified. Finish dictation and restart now?"
    if ctypes.windll.user32.MessageBoxW(None, prompt, "EXPC-WLK", 0x24) != 6:
        shutil.rmtree(work)
        return
    token = uuid.uuid4().hex
    subprocess.Popen([str(helper), str(root_path()), str(stage), str(os.getppid()), str(os.getpid()), token],
                     cwd=work, creationflags=subprocess.CREATE_NO_WINDOW)
    quit_app()


def mark_ready():
    token = os.environ.pop("EXPC_WLK_UPDATE_TOKEN", "")
    if re.fullmatch(r"[a-f0-9]{32}", token):
        path = root_path() / "WhisperKey/logs" / ("update-ready-" + token)
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text("ready", encoding="ascii")
        except OSError:
            pass  # A missing receipt causes the independent helper to roll back.
